"""PiLENS night / crime-group / A1 run, everything in ONE Kaggle cell, from scratch (2026-10-12).
What it does:
  - MoViNet-A0 features in 3 forms: normal colour, grayscale (a NoIR/IR camera gives no colour at night) and simulated night IR video.
  - Detector trained on colour -> tested on colour/gray/simulated IR. Detector trained on gray -> tested on gray/simulated IR.
  - Crime type: a SEPARATE head for 13 classes and for 4 groups (Violence, Theft, Fire/damage, Road accident), colour and gray.
  - ONNX export of the gray model (one model for day and night on the Pi).
  - MoViNet-A1 (larger model): features, detector, classes + 4 groups, ONNX export (for the Pi test).
  - If one step fails the rest continues; night results are zipped before the A1 part starts.
Night results here use SIMULATED IR only, not real night recordings.
How to run:
  1. Open the MoViNet Kaggle notebook -> "Copy & Edit". Settings: Accelerator = GPU T4, Internet = ON.
  2. Delete all old cells, add one code cell and paste this whole file.
  3. "Save Version" -> "Save & Run All (Commit)". About 5-6 hours (Kaggle limit is 12 hours), runs unattended.
  4. Download from Output: paper_pack.zip, export_movinet_a0_gray.zip and export_movinet_a1_v2.zip (for the Pi).
"""
import os, sys, zlib, base64, hashlib, subprocess, time, glob

SCRIPTS = [
    ("m_step1_extract_movinet.py", "", "f8de9b025637"),
    ("m_step2_binary_mil.py", "", "36efa0193c6e"),
    ("m_step3_14class.py", "", "f34ef4e01ae5"),
    ("m_step4_export_onnx.py", "", "bb77477e9723"),
    ("step8_save_results.py", "", "f50750e63c5f"),
]
RUNS = [
 [
  "nv",
  "1/14 features: normal colour (RGB)",
  "m_step1_extract_movinet.py",
  {
   "PILENS_TAG": "movinet_a0_v2",
   "PILENS_COLOR": "rgb"
  }
 ],
 [
  "nv",
  "2/14 features: grayscale (night/IR jaisa)",
  "m_step1_extract_movinet.py",
  {
   "PILENS_TAG": "movinet_a0_gray",
   "PILENS_COLOR": "gray"
  }
 ],
 [
  "nv",
  "3/14 features: simulated night IR (sirf 290 test videos)",
  "m_step1_extract_movinet.py",
  {
   "PILENS_TAG": "movinet_a0_irsim",
   "PILENS_COLOR": "irsim",
   "PILENS_TEST_ONLY": "1"
  }
 ],
 [
  "nv",
  "4/14 detector: RGB model (test: RGB, gray, night-sim)",
  "m_step2_binary_mil.py",
  {
   "PILENS_TAG": "movinet_a0_v2",
   "PILENS_ALT": "movinet_a0_gray,movinet_a0_irsim"
  }
 ],
 [
  "nv",
  "5/14 detector: grayscale model (test: gray, night-sim)",
  "m_step2_binary_mil.py",
  {
   "PILENS_TAG": "movinet_a0_gray",
   "PILENS_ALT": "movinet_a0_irsim"
  }
 ],
 [
  "nv",
  "6/14 crime type + 4 groups: RGB",
  "m_step3_14class.py",
  {
   "PILENS_TAG": "movinet_a0_v2"
  }
 ],
 [
  "nv",
  "7/14 crime type + 4 groups: grayscale",
  "m_step3_14class.py",
  {
   "PILENS_TAG": "movinet_a0_gray"
  }
 ],
 [
  "nv",
  "8/14 ONNX export: grayscale model (Pi, din + raat)",
  "m_step4_export_onnx.py",
  {
   "PILENS_TAG": "movinet_a0_gray",
   "PILENS_COLOR": "gray"
  }
 ],
 [
  "save",
  "9/14 results zip (night-vision results pehle hi save)",
  "step8_save_results.py",
  {}
 ],
 [
  "a1",
  "10/14 MoViNet-A1 features (RGB)",
  "m_step1_extract_movinet.py",
  {
   "PILENS_VARIANT": "A1"
  }
 ],
 [
  "a1",
  "11/14 MoViNet-A1 detector",
  "m_step2_binary_mil.py",
  {
   "PILENS_VARIANT": "A1"
  }
 ],
 [
  "a1",
  "12/14 MoViNet-A1 crime type + 4 groups",
  "m_step3_14class.py",
  {
   "PILENS_VARIANT": "A1"
  }
 ],
 [
  "a1",
  "13/14 MoViNet-A1 ONNX export (Pi)",
  "m_step4_export_onnx.py",
  {
   "PILENS_VARIANT": "A1"
  }
 ],
 [
  "save",
  "14/14 final results zip (sab kuch)",
  "step8_save_results.py",
  {}
 ]
]

print("SCRIPT VERSION: PILENS_FINAL v2.0 (2026-10-12) | MODE: FULL | night-vision (gray + IR-sim) + 4 groups + MoViNet-A1")
W = "/kaggle/working"; SRC = os.path.join(W, "pilens_nv_src"); os.makedirs(SRC, exist_ok=True)
for name, blob, sha in SCRIPTS:
    s = zlib.decompress(base64.b64decode(blob)).decode()
    assert hashlib.sha256(s.encode()).hexdigest()[:12] == sha, "file kharab ho gayi: " + name
    open(os.path.join(SRC, name), "w").write(s)

T0 = time.time()
FAILED = set()
for group, title, name, env in RUNS:
    if group in FAILED:
        print(f"\nSKIP: {title} (is group ka pichla step fail hua)"); continue
    print("\n" + "=" * 70 + f"\n>>> {title}   [{name}]   (shuru: {(time.time() - T0) / 60:.0f} min par)\n" + "=" * 70, flush=True)
    p = subprocess.Popen([sys.executable, "-u", os.path.join(SRC, name)], cwd=W, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, env={**os.environ, **env})
    for line in p.stdout:
        print(line, end="", flush=True)
    if p.wait() != 0:
        FAILED.add(group)
        print(f"\n!!! FAIL: '{title}' (exit {p.returncode}). Baaqi kaam chalta rahega; upar wala error chat mein bhejo.")

checks = [
    ("RGB features", len(glob.glob(f"{W}/feats_movinet_a0_v2/*.npy")) >= 1900),
    ("gray features", len(glob.glob(f"{W}/feats_movinet_a0_gray/*.npy")) >= 1900),
    ("night-sim test features", len(glob.glob(f"{W}/feats_movinet_a0_irsim/*.npy")) >= 290),
    ("RGB detector results", os.path.exists(f"{W}/binary_out_movinet_a0_v2/eval_pack.npz")),
    ("gray detector results", os.path.exists(f"{W}/binary_out_movinet_a0_gray/eval_pack.npz")),
    ("RGB classes + groups", os.path.exists(f"{W}/cls14_out_movinet_a0_v2/cls14_pack.npz")),
    ("gray classes + groups", os.path.exists(f"{W}/cls14_out_movinet_a0_gray/cls14_pack.npz")),
    ("download/paper_pack.zip", os.path.exists(f"{W}/download/paper_pack.zip")),
    ("download/export_movinet_a0_gray.zip", os.path.exists(f"{W}/download/export_movinet_a0_gray.zip")),
    ("A1 features", len(glob.glob(f"{W}/feats_movinet_a1_v2/*.npy")) >= 1900),
    ("A1 detector results", os.path.exists(f"{W}/binary_out_movinet_a1_v2/eval_pack.npz")),
    ("A1 classes + groups", os.path.exists(f"{W}/cls14_out_movinet_a1_v2/cls14_pack.npz")),
    ("download/export_movinet_a1_v2.zip", os.path.exists(f"{W}/download/export_movinet_a1_v2.zip")),
]
print("\n" + "=" * 70 + f"\nNIGHT-VISION RUN SUMMARY (kul {(time.time() - T0) / 60:.0f} min)")
for k, ok in checks:
    print(("  OK      " if ok else "  MISSING ") + k)
print("RUN COMPLETE: paper_pack.zip chat mein bhejo." if all(ok for _, ok in checks) else "KUCH MISSING HAI: ye summary chat mein bhejo.")
print("END OF REPORT")
